   [64]={next_id=65, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="The fact that the Coordinators knew you were coming but didn't move to intercept you... That's what bothers me.", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_412.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [65]={next_id=66, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="Hah. They're probably just scared of me, a real Void Hunter. Why else would they only dare to yap from the shadows?", msg_color="", msg_size=0, talker="Eucaly", audio="", img="arts/ui/bg/story/storybg_412.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4513", 0, 0, -22.5, 197}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [66]={next_id=67, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="Maybe... they're also wary of something else. Something that's keeping them occupied, so they're just trying to stall you.", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_412.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4513", 0, 0, -22.5, 197}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [67]={next_id=68, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="Stall? For what kind of shady business?", msg_color="", msg_size=0, talker="Eucaly", audio="", img="arts/ui/bg/story/storybg_412.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4513", 0, 0, -22.5, 197}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [68]={next_id=69, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="If I knew, would I even need to ask you?", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_412.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4513", 0, 0, -22.5, 197}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [69]={next_id=70, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="But... by now, that person should've already uncovered the Coordinators' goal.", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_412.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4513", 0, 0, -22.5, 197}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [70]={next_id=71, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="Who?", msg_color="", msg_size=0, talker="Eucaly", audio="", img="arts/ui/bg/story/storybg_412.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4513", 0, 0, -22.5, 197}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [71]={next_id=72, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="Your mission target—don't tell me you forgot.", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_412.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4513", 0, 0, -22.5, 197}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [72]={next_id=73, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="...You mean that Linker from Leistance? I've been wandering this city for hours and haven't seen a trace of him. Probably dead in some sewer by now.", msg_color="", msg_size=0, talker="Eucaly", audio="", img="arts/ui/bg/story/storybg_412.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4513", 0, 0, -22.5, 197}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [73]={next_id=74, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="I gave you the most likely location to find him. And I already know you didn't go there first. So if you're lying right now and saying you forgot, I swear I'll fly over from the Arctic and cut out your tongue.", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_412.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4513", 0, 0, -22.5, 197}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [74]={next_id=75, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="...Tch.", msg_color="", msg_size=0, talker="Eucaly", audio="", img="arts/ui/bg/story/storybg_412.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4513", 0, 0, -22.5, 197}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [75]={next_id=76, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="Why is he so important? He's just some ordinary grunt working for Leistance. Meanwhile, we're above even them!", msg_color="", msg_size=0, talker="Eucaly", audio="", img="arts/ui/bg/story/storybg_412.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4513", 0, 0, -22.5, 197}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [76]={next_id=77, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="...There are only two people in this world who have the unconditional trust of the Void Hunters. One of them goes without saying, and the other—", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_412.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [77]={next_id=78, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="This person might not know us yet, but your job is to make sure he finds out who you are and then listen to what he has to say.", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_412.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [78]={next_id=79, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="He's a Linker from Leistance.", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_412.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [79]={next_id=80, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="...You want me to take orders from him temporarily?", msg_color="", msg_size=0, talker="Eucaly", audio="", img="arts/ui/bg/story/storybg_412.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4513", 0, 0, -22.5, 197}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [80]={next_id=81, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="Eucaly's voice twisted with disbelief.", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_412.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4513", 0, 0, -22.5, 197}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [81]={next_id=82, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="Listen, I don't care who this Linker is supposed to be. I won't let some human command me. No one dictates my actions!", msg_color="", msg_size=0, talker="Eucaly", audio="", img="arts/ui/bg/story/storybg_412.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4513", 0, 0, -22.5, 197}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [82]={next_id=83, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="If this so-called Linker is really alive, then I'll make sure he obeys me and sticks to his role as a supporting character.", msg_color="", msg_size=0, talker="Eucaly", audio="", img="arts/ui/bg/story/storybg_412.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4513", 0, 0, -22.5, 197}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [83]={next_id=84, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="...If you can pull that off, be my guest.", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_412.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4513", 0, 0, -22.5, 197}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [84]={next_id=85, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="The contact location hasn't changed—still that bar. Don't drag your feet. Once the mission's over, you'll have plenty of time to enjoy the comforts of civilized society.", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_412.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4513", 0, 0, -22.5, 197}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [85]={next_id=86, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="And keep a low profile. If the Star Council finds out a Void Hunter left the Arctic without authorization... You know the consequences.", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_412.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4513", 0, 0, -22.5, 197}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [86]={next_id=87, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="*Beep* Call ended.", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_412.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4513", 0, 0, -22.5, 197}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [87]={next_id=88, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="*Bang* Eucaly hurled the communicator against the wall, reducing it to a pile of electronic scrap.", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_412.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4513", 0, 0, -22.5, 197}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [88]={next_id=89, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="Just some acting captain, and she dares talk to me like that... That position should've been mine!", msg_color="", msg_size=0, talker="Eucaly", audio="", img="arts/ui/bg/story/storybg_412.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4513", 0, 0, -22.5, 197}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [89]={next_id=90, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="I'll take that spot sooner or later. And when I do... I'll make sure you kneel and lick my boots!", msg_color="", msg_size=0, talker="Eucaly", audio="", img="arts/ui/bg/story/storybg_412.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4513", 0, 0, -22.5, 197}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [90]={next_id=91, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="As for that Linker... Hmph.", msg_color="", msg_size=0, talker="Eucaly", audio="", img="arts/ui/bg/story/storybg_412.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "4513", 0, 0, -22.5, 197}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [91]={next_id=92, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="With a dismissive snort, Eucaly slung her blade over her shoulder. She'd already decided how to make that stranger submit to her.", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_412.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
